<script setup lang="ts">
import { computed, onMounted, shallowRef } from 'vue'
import { Refresh } from '@element-plus/icons-vue'
import { getApiError } from '../api/http'
import { getMonitoringOverview, listAlertStates, setAlertEnabled, type AlertState, type MonitoringOverview } from '../api/observability'

const overview = shallowRef<MonitoringOverview | null>(null)
const alerts = shallowRef<AlertState[]>([])
const loading = shallowRef(false)
const errorMessage = shallowRef('')
const traceId = shallowRef('')
const serviceChecks = computed(() => overview.value?.readiness.checks || [])
function statusType(status: string) { return ['ok', 'OK'].includes(status) ? 'success' : ['down', 'ALERT'].includes(status) ? 'danger' : 'warning' }
function percent(value: number) { return `${Math.round(value * 100)}%` }
function bytes(value: number) { const units = ['B', 'KB', 'MB', 'GB', 'TB']; let index = 0; let current = value; while (current >= 1024 && index < units.length - 1) { current /= 1024; index += 1 }; return `${current.toFixed(index ? 1 : 0)} ${units[index]}` }
async function loadMonitoring() { loading.value = true; errorMessage.value = ''; try { const [nextOverview, nextAlerts] = await Promise.all([getMonitoringOverview(), listAlertStates()]); overview.value = nextOverview; alerts.value = nextAlerts.items } catch (error) { const detail = getApiError(error); errorMessage.value = detail.message; traceId.value = detail.traceId } finally { loading.value = false } }
async function toggleAlert(alert: AlertState) { try { alerts.value = (await setAlertEnabled(alert.code, !alert.enabled)).items } catch (error) { errorMessage.value = getApiError(error).message } }
onMounted(loadMonitoring)
</script>

<template>
  <section class="observability-page"><div class="observability-toolbar"><div><span class="eyebrow">SYSTEM / OPERATIONS MONITORING</span><h2>运行监控</h2><p>MySQL、Chroma、模型、磁盘、错误率、P95 延迟和可关闭告警。</p></div><el-button :loading="loading" @click="loadMonitoring"><el-icon><Refresh /></el-icon>刷新监控</el-button></div><el-alert v-if="errorMessage" class="page-alert" type="error" :closable="false" show-icon :title="errorMessage"><template #default><span v-if="traceId">trace_id: {{ traceId }}</span><el-button text type="primary" @click="loadMonitoring">重试</el-button></template></el-alert><template v-if="overview"><div class="monitor-metric-grid"><div class="monitor-metric"><span>请求数</span><strong>{{ overview.telemetry.request_count }}</strong><small>进程采样窗口</small></div><div class="monitor-metric"><span>错误率</span><strong>{{ percent(overview.telemetry.error_rate) }}</strong><small>{{ overview.telemetry.error_count }} 个错误</small></div><div class="monitor-metric"><span>P95 延迟</span><strong>{{ overview.telemetry.p95_latency_ms }} ms</strong><small>HTTP 请求</small></div><div class="monitor-metric"><span>磁盘使用</span><strong>{{ percent(overview.disk.used_ratio) }}</strong><small>{{ bytes(overview.disk.free_bytes) }} 可用</small></div></div><div class="monitor-grid"><el-card class="observability-card"><template #header><div class="card-header"><div><strong>依赖健康</strong><small>{{ overview.readiness.status }}</small></div><el-tag :type="overview.readiness.ready ? 'success' : 'warning'">{{ overview.readiness.ready ? 'READY' : 'DEGRADED' }}</el-tag></div></template><div class="service-check-list"><div v-for="check in serviceChecks" :key="check.service"><span><i class="status-dot" :class="{ 'status-dot--warning': check.status !== 'ok' }" />{{ check.service }}</span><el-tag size="small" :type="statusType(check.status)">{{ check.status }}</el-tag><small>{{ check.detail }}</small></div></div></el-card><el-card class="observability-card"><template #header><div class="card-header"><div><strong>告警控制</strong><small>关闭和恢复操作会写入审计日志</small></div></div></template><div class="alert-list"><div v-for="alert in alerts" :key="alert.code" class="alert-row"><div><strong>{{ alert.label }}</strong><small>{{ alert.code }} · {{ alert.detail }}</small></div><el-tag size="small" :type="statusType(alert.current_status)">{{ alert.current_status }}</el-tag><el-switch v-model="alert.enabled" :active-text="alert.enabled ? '开' : '关'" @change="toggleAlert(alert)" /></div></div></el-card></div><div class="monitor-grid"><el-card class="observability-card"><template #header><div class="card-header"><div><strong>组件耗时</strong><small>模型、Embedding、RAG、工具和请求采样</small></div></div></template><el-table :data="Object.entries(overview.components).map(([name, value]) => ({ name, ...value }))" size="small" empty-text="暂无耗时样本"><el-table-column prop="name" label="组件" /><el-table-column prop="count" label="调用数" width="90" /><el-table-column prop="error_count" label="错误数" width="90" /><el-table-column prop="p95_latency_ms" label="P95 ms" width="100" /></el-table></el-card><el-card class="observability-card"><template #header><div class="card-header"><div><strong>业务统计</strong><small>运行、导入和审计记录</small></div></div></template><div class="monitor-stat-list"><div><span>Agent 已完成</span><strong>{{ overview.agent_runs.COMPLETED || 0 }}</strong></div><div><span>Agent 失败/阻塞</span><strong>{{ (overview.agent_runs.FAILED || 0) + (overview.agent_runs.BLOCKED || 0) }}</strong></div><div><span>导入失败/部分</span><strong>{{ (overview.imports.FAILED || 0) + (overview.imports.PARTIAL || 0) }}</strong></div><div><span>近 24 小时审计</span><strong>{{ overview.audit.last_24h }}</strong></div></div></el-card></div></template><el-empty v-else-if="!loading" description="暂无监控数据" /></section>
</template>
